package accesscatalog

import (
	"bytes"
	"fmt"
	"strings"

	"sigs.k8s.io/yaml"
)

const chartTemplateHeader = `# Copyright (c) Microsoft Corporation.
# Licensed under the MIT License.

# Code generated by tools/access-catalog; DO NOT EDIT.
# Source of truth: internal/accesscatalog. Regenerate with: go run ./tools/access-catalog

`

const (
	chartTemplateGuard = `{{- if and (eq .Values.mode "kubernetes") .Values.rbac.humanRoles.enabled }}`
	chartTemplateEnd   = `{{- end }}`
	chartLabelsHelper  = `{{- include "kognition.labels" . | nindent 4 }}`
)

// RenderChartTemplate renders the human roles as a Helm template. The output is
// deterministic. The roles are rendered only in Kubernetes mode and when
// rbac.humanRoles.enabled is true, and they carry no bindings.
func (c Catalog) RenderChartTemplate() ([]byte, error) {
	roles, err := c.ClusterRoles()
	if err != nil {
		return nil, err
	}
	var out bytes.Buffer
	out.WriteString(chartTemplateHeader)
	out.WriteString(chartTemplateGuard + "\n")
	for _, role := range roles {
		rules, err := yaml.Marshal(role.Rules)
		if err != nil {
			return nil, fmt.Errorf("render rules for %s: %w", role.Name, err)
		}
		fmt.Fprintf(&out, "---\napiVersion: %s\nkind: %s\nmetadata:\n  name: %s\n  labels:\n    %s\n    %s: %s\nrules:\n",
			role.APIVersion, role.Kind, role.Name, chartLabelsHelper, RoleLabel, role.Labels[RoleLabel])
		for _, line := range strings.Split(strings.TrimRight(string(rules), "\n"), "\n") {
			out.WriteString("  " + line + "\n")
		}
	}
	out.WriteString(chartTemplateEnd + "\n")
	return out.Bytes(), nil
}
